abstract class DataIngestionPipeline {
    public final void runPipeline(String source) {
        readSource(source);
        if (shouldCompress()) {
            compress();
        }
        saveData();
    }
    private void readSource(String source) {
        System.out.println("[Read] Ingesting " + source);
    }
    protected boolean shouldCompress() {
        return false;
    }
    private void compress() {
        System.out.println("[Compress] Applying GZIP compression");
    }
    protected abstract void saveData();
}

class StandardIngestion extends DataIngestionPipeline {
    @Override
    protected void saveData() {
        System.out.println("[Save] Writing raw records to warehouse");
    }
}

class ArchivalIngestion extends DataIngestionPipeline {
    @Override
    protected boolean shouldCompress() {
        return true;
    }
    @Override
    protected void saveData() {
        System.out.println("[Save] Archiving compressed payload to cold storage");
    }
}

public class PipelineApp {
    public static void main(String[] args) {
        DataIngestionPipeline pipeline = new ArchivalIngestion();
        pipeline.runPipeline("sensor_logs.csv");
    }
}

abstract class GameCharacter {
    protected String name;
    protected int health = 100;
    public GameCharacter(String name) {
        this.name = name;
    }
    public void takeDamage(int amt) {
        this.health -= amt;
        System.out.println(name + " takes " + amt + " damage (Health: " + health + ")");
    }
    public final void takeTurn() {
        System.out.println("--- " + name + "'s Turn ---");
        chooseAction();
        postTurnCleanup();
    }
    protected abstract void chooseAction();
    protected void postTurnCleanup() {
        System.out.println(name + " finishes turn safely");
    }
}

class Warrior extends GameCharacter {
    public Warrior(String name) { super(name); }
    @Override
    protected void chooseAction() {
        System.out.println(name + " swings broadsword for heavy strike!");
    }
}

class Wizard extends GameCharacter {
    public Wizard(String name) { super(name); }
    @Override
    protected void chooseAction() {
        System.out.println(name + " casts Arcane Shield!");
    }
    @Override
    protected void postTurnCleanup() {
        System.out.println(name + " regenerates 5 mana points");
    }
}

public class GameApp {
    public static void main(String[] args) {
        GameCharacter[] party = new GameCharacter[] {
            new Warrior("Conan"),
            new Wizard("Gandalf")
        };
        for (GameCharacter c : party) {
            c.takeTurn();
        }
    }
}

